#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    std::vector<int> sortByAbsoluteValue(std::vector<int>& nums) {
        std::stable_sort(nums.begin(), nums.end(), [](int a, int b) {
            return std::abs(a) < std::abs(b);
        });
        return nums;
    }
};

import java.util.*;

class Solution {
    public int[] sortByAbsoluteValue(int[] nums) {
        Integer[] boxed = Arrays.stream(nums).boxed().toArray(Integer[]::new);
        Arrays.sort(boxed, Comparator.comparingInt(Math::abs));
        for (int i = 0; i < nums.length; i++) nums[i] = boxed[i];
        return nums;
    }
}

var sortByAbsoluteValue = function(nums) {
    return nums.slice().sort((a, b) => Math.abs(a) - Math.abs(b));
};
